bundle.text:
# 注册本 bundle 携带的技能到 DSH 技能系统。
#
# 关键：customSkillDirs 用 !!js 表达式在装载时基于 loader.filename / baseUrl 动态
# 解析出「本包在 <profile>/node_modules/dsh-we-wallpaper-sync/skills」的绝对路径，
# 因此无论安装到哪个 profile、哪种布局都能解析，无需用户手工改配置。
# （同 @volcengine/ark-managed-agents 的 loader.filename + createRequire 手法。）
- insert:
    - id: dsh-we-wallpaper-sync-skill
      name: '@deepseek-ai/dsh-skill-filesystem'
      config:
        providerName: dsh-we-wallpaper-sync
        includeDefaultRoots: false
        customSkillDirs:
          - !!js >-
              (function(){
                var M = process.getBuiltinModule('node:module');
                var path = process.getBuiltinModule('node:path');
                var anchors = [];
                try { if (typeof baseUrl!=='undefined' && baseUrl) anchors.push(baseUrl); } catch(e){}
                try { if (typeof loader!=='undefined' && loader && loader.filename) anchors.push(loader.filename); } catch(e){}
                try { if (typeof loader!=='undefined' && loader && loader.url) anchors.push(loader.url); } catch(e){}
                try { anchors.push(dshHomePath('profiles','web','package.json')); } catch(e){}
                try { anchors.push(process.cwd()+'/'); } catch(e){}
                var spec = 'dsh-we-wallpaper-sync/package.json';
                var last;
                for (var i=0;i<anchors.length;i++){
                  try {
                    var root = path.dirname(M.createRequire(anchors[i]).resolve(spec));
                    return path.join(root, 'skills');
                  } catch(e){ last = e; }
                }
                throw new Error('dsh-we-wallpaper-sync: cannot resolve skills dir from ' + anchors.join(',') + (last ? (': ' + last) : ''));
              })()
